diff --git a/server/routes/saved.ts b/server/routes/saved.ts
index 2c9f1ab..e7a50d3 100644
--- a/server/routes/saved.ts
+++ b/server/routes/saved.ts
@@ -1,36 +1,44 @@
 import { Router } from "express";
 import { db } from "../db";
 import { requireUser } from "../auth";

 export const saved = Router();

+type SavedRow = {
+  id: string;
+  recipe_id: string;
+  title: string;
+  saved_at: Date;
+  private_notes: string | null;
+};
+
 saved.get("/api/recipes/saved", requireUser, async (req, res) => {
   const userId = req.user!.id;
-  const limit = Math.min(Number(req.query.limit) || 50, 100);
-  const offset = Math.max(Number(req.query.offset) || 0, 0);
-  const { rows } = await db.query(
-    `SELECT ur.id, ur.recipe_id, r.title, ur.saved_at, ur.notes
-       FROM user_recipes ur JOIN recipes r ON r.id = ur.recipe_id
-      WHERE ur.user_id = $1
-      ORDER BY ur.saved_at DESC
-      LIMIT $2 OFFSET $3`,
-    [userId, limit, offset],
-  );
-  res.json({ items: rows });
+  const limit = Math.min(Number(req.query.limit) || 50, 100);
+  const cursor = typeof req.query.cursor === "string" ? req.query.cursor : null;
+
+  const { rows } = await db.query<SavedRow>(
+    `SELECT ur.id, ur.recipe_id, r.title, ur.saved_at, ur.private_notes
+       FROM user_recipes ur JOIN recipes r ON r.id = ur.recipe_id
+      WHERE ur.user_id = $1
+      ORDER BY ur.saved_at DESC, ur.id DESC`,
+    [userId],
+  );
+
+  const start = cursor ? rows.findIndex((r) => r.id === cursor) + 1 : 0;
+  const page = rows.slice(start, start + limit);
+  const nextCursor =
+    start + limit < rows.length ? page[page.length - 1].id : null;
+
+  res.json({ items: page, nextCursor });
 });
